import { FC, useEffect, useState, useRef,useCallback } from 'react';
import LightGallery from 'lightgallery/react';
import lgZoom from 'lightgallery/plugins/zoom';
import imagesLoaded from 'imagesloaded';
import Select from 'react-select'
import makeAnimated from 'react-select/animated';

import './style.scss';
import imageDataArray from './imageMetadata.json';
console.log(imageDataArray);

const animatedComponents = makeAnimated();

export const App: FC<{ name: string }> = ({ name }) => {
  const lightGallery = useRef<any>(null);

  const [filteredImageData, setFilteredImageData] = useState(imageDataArray)

  const onInit = useCallback((detail) => {
        if (detail) {
            lightGallery.current = detail.instance;
        }
    }, []);

  useEffect(() => {
        console.log("refresh")
        lightGallery.current.refresh();
    }, [filteredImageData]);


  const filterImages = (filters) => {
    if (filters.length === 0) {      
      setFilteredImageData([...imageDataArray])
      return
    }
    const filteredSpecies = new Set(filters.map(filter => filter.value))
    setFilteredImageData(imageDataArray.filter(image => filteredSpecies.has(image.species)))
  }

  const getUniqueSpeciesNames = () => {
    return Array.from(new Set(imageDataArray.map(item => item.species)));
  };

  const getItems = useCallback(() => {
      console.log("get items");
      
        return filteredImageData.map((imageData, index) => (
            

              <a
                // data-lg-size="1600-1067"
                className="gallery__item"
                data-src={`./images/${imageData.src}`}
                // data-large-size={imageData.fullSize}
                // data-lg-size={imageData.fullSize}
                data-sub-html={`<h4>${imageData.species}</h4><p>Photo by - Mark Fajet, Location - ${imageData.location}, Capture date - ${imageData.dateCaptured}</p>${imageData.ig? `<a href="$\{imageData.ig\}">Instagram Link</a>`: ""}`}
                data-download-url={false}
                key={`${imageData.src}-${index}`}
              >
                <img
                  alt={imageData.species}
                  className="img-responsive"
                  src={`./images/thumbnails/${imageData.src}`}
                />
              </a>
          ))
    }, [filteredImageData]);

  const sortOptions = [
    { value: "dateCaptured", label: "Capture Date" },
    { value: "species", label: "Species" },
  ]

  const sortImages = (selection) => {    
    setFilteredImageData([...filteredImageData].sort((a,b) => a[selection.value].localeCompare(b[selection.value])));
    console.log("sorted");
    
  }

  return (
    <div className="App">
      <HeaderComponent />
      <Select
        closeMenuOnSelect={true}
        options={sortOptions}
        onChange={(e) => sortImages(e)}
        placeholder="Sort"
      />
      <Select
        closeMenuOnSelect={false}
        components={animatedComponents}
        isMulti
        options={getUniqueSpeciesNames().map((species) => ({ value: species, label: species }))}
        onChange={(e) => filterImages(e)}
        placeholder="Filter by species"
      />
      <LightGallery
        download={false}
        onInit={onInit}
        // plugins={[lgZoom]}
        mode="lg-fade"
        pager={false}
        thumbnail={true}
        galleryId={'nature'}
        elementClassNames={'gallery'}
        mobileSettings={{
          controls: false,
          showCloseIcon: false,
          download: false,
          rotate: false,
        }}

      >

        {getItems()}

      </LightGallery>
    </div>
  );
};

const HeaderComponent: React.FC = () => (
  <div className="header">
    <h1 className="header__title">Mark Fajet photography</h1>
    <p className="header__description">
      I mostly take photos of birds. They are ungrateful and do not pay me for taking these photos of them.
    </p>
    <a
      className="header__button"
      href="https://www.instagram.com/markmybirds.photography/"
      target="_blank"
    >
      Follow my Instagram
    </a>
  </div>
);
